import uuid
import time


def generate_ulid_with_prefix(prefix: str) -> str:
    """Generate a unique ID with prefix for data migration (simplified ULID-like)."""
    timestamp = int(time.time() * 1000)
    random_part = uuid.uuid4().hex[:16].upper()
    return f"{prefix}_{timestamp}{random_part}"


