def migrate_existing_users(apps, schema_editor):
    """Migrate existing users to new system."""
    
    User = apps.get_model('account', 'User')
    UserRole = apps.get_model('account', 'UserRole')
    Role = apps.get_model('account', 'Role')
    UserStatus = apps.get_model('account', 'UserStatus')
    
    # Get default role and status
    try:
        user_role = Role.objects.get(slug='user')
        admin_role = Role.objects.get(slug='admin')
        pending_status = UserStatus.objects.get(slug='pending')
        active_status = UserStatus.objects.get(slug='active')
    except (Role.DoesNotExist, UserStatus.DoesNotExist):
        # Seed data should have been created already
        return
    
    # Migrate all existing users
    for user in User.objects.all():
        # Generate user_id if not present
        if not user.user_id:
            user.user_id = generate_ulid_with_prefix("usr")
        
        # Determine role based on old is_staff/is_superuser (replaces is_admin)
        if user.is_staff or user.is_superuser:
            target_role = admin_role
            target_status = active_status
            user.email_verified = True
            user.email_verified_at = timezone.now()
        else:
            target_role = user_role
            target_status = pending_status
        
        # Set status
        user.status = target_status
        
        # Save user with new fields
        user.save(update_fields=['user_id', 'status', 'email_verified', 'email_verified_at'])
        
        # Create UserRole relationship
        UserRole.objects.get_or_create(
            user=user,
            role=target_role,
            defaults={
                'userrole_id': generate_ulid_with_prefix("ur")
            }
        )


